<script setup lang="ts">
import SummaryFacts from "@lottery/shared/SummaryFacts.vue"
import {ref,onMounted,onBeforeUnmount,computed,watch} from 'vue'
import {vGlobalLoading} from '@lottery/shared'
import PaginationControls from '@lottery/shared/PaginationControls.vue'
import OrderHistoryRecord from '@lottery/shared/OrderHistoryRecord.vue'
import MembersPage from './MembersPage.vue'
import {request,AgentError} from '../api'
import {i18n} from '../i18n'
import type {Member,MemberScope,Bet,Wallet} from '../types'
const props=defineProps<{memberId:string|null;scope:MemberScope}>(),emit=defineEmits<{select:[member:Member,scope:MemberScope];clear:[];'session-invalid':[]}>(),{t,locale}=i18n
const info=ref<{member:Member;wallet:Wallet;net_points:string;unsettled_points:string}|null>(null),bets=ref<Bet[]>([]),cursor=ref<string|null>(null),loading=ref(false),error=ref<unknown>(null),errorText=computed(()=>i18n.errorText(error.value));const pageIndex=ref(0),cursors=ref<Array<string|null>>([null]);let generation=0
async function load(index=0){if(!props.memberId)return;const ticket=++generation;loading.value=true;error.value=null;try{const path=`/members/${encodeURIComponent(props.memberId)}`;if(index===0){const summary=await request<NonNullable<typeof info.value>>(path+`/summary?scope=${props.scope}`);if(ticket!==generation)return;info.value=summary}const page=await request<{items:Bet[];next_cursor:string|null}>(path+`/bets?scope=${props.scope}&limit=20${cursors.value[index]?'&cursor='+encodeURIComponent(cursors.value[index]!):''}`);if(ticket===generation){bets.value=page.items;pageIndex.value=index;cursor.value=page.next_cursor;cursors.value=cursors.value.slice(0,index+1);if(page.next_cursor)cursors.value.push(page.next_cursor)}}catch(e){if(ticket!==generation)return;error.value=e;if(e instanceof AgentError&&e.status===401)emit('session-invalid')}finally{if(ticket===generation)loading.value=false}}
watch(()=>[props.memberId,props.scope],()=>{generation++;info.value=null;bets.value=[];cursor.value=null;pageIndex.value=0;cursors.value=[null];void load()});onMounted(()=>load());onBeforeUnmount(()=>generation++)
</script>
<template><MembersPage v-if="!memberId" pick @bets="(member,scope)=>emit('select',member,scope)" @session-invalid="emit('session-invalid')"/><section v-else class="panel console-panel console-stack member-bets"><div class="section-head panel-header"><strong>{{info?.member.username}}</strong><button class="button button-secondary" @click="emit('clear')">{{t('selectMember')}}</button></div><p v-global-loading v-if="loading" role="status">{{t('loading')}}</p><p v-if="error" class="message error" role="alert">{{errorText}}</p><SummaryFacts class="console-facts--cards" v-if="info" :fields="[{label:t('points'),value:info.wallet.available_points},{label:t('profit'),value:info.net_points},{label:t('pending'),value:info.unsettled_points}]" /><p class="muted">{{t('netHelp')}}</p><div class="console-stack"><OrderHistoryRecord v-for="bet in bets" :key="`${bet.kind}:${bet.id}`" :item="bet" :locale="locale" /></div><p v-if="!loading&&!error&&!bets.length" class="empty-state">{{t('empty')}}</p><PaginationControls :summary="t('pageNumber',{number:pageIndex+1})" :previous-label="t('previous')" :next-label="t('next')" :busy="loading" :has-previous="pageIndex>0" :has-next="Boolean(cursor)" :previous="async()=>{await load(pageIndex-1)}" :next="async()=>{await load(pageIndex+1)}" /></section></template>
